+  const downgradedContextPackRefs = downgradedContextIds
+    .map((id) => provisionalById.get(id))
+    .filter(isRecord)
+    .map((assertion) => packRefForAssertion({
+      assertion,
+      questionId,
+      sourceField: 'provisional_safe_assertions',
+      semanticContext: 'provisional_degraded',
